describe('Payment Processing Loading State', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should display loading state while payment is processing', () => {
    // Intercept the payment API call
    cy.intercept('POST', '/api/payments/process', {
      statusCode: 200,
      body: {
        success: true,
        transactionId: '123456789',
        amount: 100.00,
        currency: 'USD',
        status: 'completed'
      }
    }).as('paymentProcess');

    // Verify initial payment form is visible
    cy.get('[data-testid="payment-form"]').should('be.visible');

    // Fill in payment details
    cy.get('[data-testid="card-number"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date"]').type('12/25');
    cy.get('[data-testid="cvv"]').type('123');

    // Verify loading spinner is visible
    cy.get('[data-testid="loading-spinner"]').should('be.visible');

    // Click the submit button
    cy.get('[data-testid="submit-payment-btn"]').click();

    // Wait for payment API call to complete
    cy.wait('@paymentProcess');

    // Verify loading spinner is hidden
    cy.get('[data-testid="loading-spinner"]').should('not.exist');

    // Verify success message appears
    cy.get('[data-testid="payment-success-message"]').should('be.visible');
    cy.get('[data-testid="payment-success-message"]').should('contain', 'Payment processed successfully');

    // Verify payment details are cleared
    cy.get('[data-testid="card-number"]').should('have.value', '');
    cy.get('[data-testid="expiry-date"]').should('have.value', '');
    cy.get('[data-testid="cvv"]').should('have.value', '');

    // Verify order confirmation page is displayed
    cy.url().should('include', '/order-confirmation');
  });

  it('should display error state when payment fails', () => {
    // Intercept the payment API call with error response
    cy.intercept('POST', '/api/payments/process', {
      statusCode: 500,
      body: {
        success: false,
        error: 'Internal server error',
        transactionId: null
      }
    }).as('paymentError');

    // Fill in payment details
    cy.get('[data-testid="card-number"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date"]').type('12/25');
    cy.get('[data-testid="cvv"]').type('123');

    // Verify loading spinner is visible
    cy.get('[data-testid="loading-spinner"]').should('be.visible');

    // Click the submit button
    cy.get('[data-testid="submit-payment-btn"]').click();

    // Wait for payment API call to complete
    cy.wait('@paymentError');

    // Verify loading spinner is still visible
    cy.get('[data-testid="loading-spinner"]').should('be.visible');

    // Verify error message appears
    cy.get('[data-testid="payment-error-message"]').should('be.visible');
    cy.get('[data-testid="payment-error-message"]').should('contain', 'Payment failed');

    // Verify payment details are still visible
    cy.get('[data-testid="card-number"]').should('have.value', '4111111111111111');

    // Verify retry button is available
    cy.get('[data-testid="retry-payment-btn"]').should('be.visible');

    // Verify order confirmation page is not displayed
    cy.url().should('not.include', '/order-confirmation');
  });
});
